style.css:
@-moz-document url-prefix("https://chatgpt.com/") {
/* Fondo solo en el área del chat */
  main {
    background-image: url("https://i.imgur.com/L3vzJOt.jpeg") !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-size: cover !important;
    background-color: #000000 !important;
  }

  /* Estilo para las respuestas */
  div[class*="markdown"] {
    background: rgba(0, 0, 0, 0.65) !important;
    color: #ffffff !important;
    padding: 12px !important;
    border-radius: 12px !important;
    margin: 8px 0 !important;
    text-decoration: underline !important;
    text-decoration-color: #a0a0a0 !important;
    text-decoration-thickness: 1.5px !important;
  }

  /* Estilo para el cuadro de texto y inputs */
  textarea, input {
    background: rgba(20, 20, 20, 0.8) !important;
    color: #ffffff !important;
  }
}
